    explanation: '印紙税は文書の作成に対して課される税で、課税物件は印紙税法別表第一に掲げられた文書に限られる。不動産の譲渡に関する契約書は第1号の1文書、地上権または土地の賃借権の設定・譲渡に関する契約書は第1号の2文書として課税されるが、建物の賃貸借契約書は課税物件に掲げられておらず課税されない。また媒介契約書や委任状も課税文書に当たらない。土地と建物で扱いが分かれる点が繰り返し問われている。\n\n【図解】不動産関係文書の課否\n　文書の種類｜印紙税｜根拠\n　不動産の売買契約書｜課税｜第1号の1文書\n　土地の賃貸借契約書｜課税｜第1号の2文書\n　建物の賃貸借契約書｜課税されない｜課税物件でない\n　⇒ 媒介契約書や委任状も課税文書に該当しない。\n　⚠ 土地の賃貸借は課税、建物の賃貸借は不課税。最頻出の区別である。',
