    explanation: '新築住宅の不動産取得税は、床面積が50㎡以上240㎡以下（一戸建て以外の貸家住宅は40㎡以上）である場合、課税標準となる固定資産税評価額から1戸につき1,200万円を控除して計算する。評価額1,500万円・床面積80㎡の新築住宅であれば、1,500万円から1,200万円を控除した300万円が課税標準となり、これに住宅の税率3パーセントを乗じた9万円が税額となる。認定長期優良住宅であれば控除額は1,300万円となり、税額はさらに小さくなる。\n\n【図解】計算例（評価額1,500万円・80㎡）\n　段階｜計算｜結果\n　控除前の評価額｜固定資産税評価額｜1,500万円\n　1,200万円控除後｜1,500万円から1,200万円を控除｜課税標準300万円\n　税額｜300万円に3％を乗じる｜9万円\n　⇒ 認定長期優良住宅なら控除額が1,300万円となり課税標準は200万円となる。\n　⚠ 控除するのは税額からではなく課税標準からである。税額控除と混同しないこと。',
