    explanation: '不動産に関する主な税のうち、不動産取得税は都道府県が課する道府県税、固定資産税と都市計画税は市町村が課する市町村税、登録免許税・印紙税・所得税は国税である。徴収方法も異なり、不動産取得税と固定資産税は納税通知書による普通徴収、登録免許税は登記を受ける時までに現金または印紙で納付、印紙税は課税文書への印紙の貼付と消印による。相続による取得は不動産取得税では非課税だが、登録免許税では1000分の4で課税される。\n\n【図解】主な不動産関係税の区分\n　税目｜国税か地方税か｜納付の方法\n　不動産取得税｜都道府県税｜普通徴収（納税通知書）\n　固定資産税・都市計画税｜市町村税｜普通徴収（納税通知書）\n　登録免許税・印紙税｜国税｜登記時の納付・印紙の貼付\n　⇒ 課税団体と納付方法をセットで覚えると横断問題に対応しやすい。\n　⚠ 登録免許税を地方税と誤解しないこと。登記に対して課される国税である。',
